function showError(e,r){apex.item(r).setFocus(),apex.message.clearErrors(),apex.message.showErrors([{type:"error",location:"inline",pageItem:r,message:e,unsafe:!1},{type:"error",location:"inline",message:"An error has occurred.",unsafe:!1}])}function disablefield(e){apex.item(e).disable()}function enablefield(e){apex.item(e).enable()}function mergeReportColumn(e,r){$("#report_"+e+", #"+e).find(".t-Report-report, table").each((function(){var e=$(this),t=null;e.find("tbody tr").each((function(){var e=$(this).find("td").eq(r-1);if(0!==e.length){var o=e.text().trim();if(null===t)t=e;else if(o===t.text().trim()&&""!==o){var n=parseInt(t.attr("rowspan"))||1;t.attr("rowspan",n+1),t.css({"border-bottom":"1px solid #e6e6e6","vertical-align":"middle","background-color":"#ffffff"}),e.remove()}else t=e}}))}))}function runMergeAutomation(){$(".t-report-merge-column1").each((function(){var e=$(this).closest("[id]").attr("id");e&&0===e.indexOf("report_")&&(e=e.replace("report_","")),mergeReportColumn(e,1)})),$(".t-report-merge-column2").each((function(){var e=$(this).closest("[id]").attr("id");e&&0===e.indexOf("report_")&&(e=e.replace("report_","")),mergeReportColumn(e,2)}))}$(document).ready((function(){runMergeAutomation()})),$(document).on("apexafterrefresh",(function(){runMergeAutomation()}));